-- =====================================================================
-- 01_schema.sql  -  Airline Reservation System : tables & constraints
--
-- Entities : airlines, airports, aircraft, flights, passengers, seats,
--            bookings, payments, crew, flight_crew
-- Support  : booking_audit_log (filled by trigger trg_bookings_audit)
--
-- Design notes
--  * Surrogate keys are IDENTITY columns (GENERATED BY DEFAULT ON NULL)
--    starting at 1000. Seed data in 02_data.sql uses explicit ids below
--    1000, so identity values generated later can never collide with it.
--  * A booking stores only passenger_id + seat_id. The flight is reached
--    through seats.flight_id, so it is stored once (3NF).
--  * ON DELETE CASCADE  : airline->aircraft/flights/crew, flight->seats,
--                         passenger->bookings, booking->payment,
--                         flight/crew->flight_crew
--    ON DELETE SET NULL : flights.aircraft_id (an aircraft can be retired
--                         without deleting its flight history)
--    No action (restrict): airports, and bookings.seat_id - a flight that
--                         still has bookings cannot be deleted.
--  * Partial unique index uq_bookings_active_seat makes "one CONFIRMED
--    booking per seat" a database guarantee even under concurrency.
--
-- Usage:  SQL> @01_schema.sql
-- =====================================================================
SET ECHO OFF
SET SERVEROUTPUT ON SIZE UNLIMITED FORMAT WRAPPED
SET LINESIZE 200
SET PAGESIZE 50
SET FEEDBACK ON
SET VERIFY OFF
SET DEFINE OFF
SET SQLBLANKLINES ON

PROMPT
PROMPT ==== 01_schema.sql : creating tables ====

-- ---------------------------------------------------------------------
-- AIRLINES
-- ---------------------------------------------------------------------
CREATE TABLE airlines (
  airline_id    NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH 1000)
                CONSTRAINT pk_airlines PRIMARY KEY,
  iata_code     VARCHAR2(2)  NOT NULL
                CONSTRAINT uq_airlines_code UNIQUE
                CONSTRAINT ck_airlines_code CHECK (REGEXP_LIKE(iata_code, '^[A-Z0-9]{2}$')),
  airline_name  VARCHAR2(60) NOT NULL
                CONSTRAINT uq_airlines_name UNIQUE,
  country       VARCHAR2(40) NOT NULL,
  founded_year  NUMBER(4)
                CONSTRAINT ck_airlines_year CHECK (founded_year BETWEEN 1900 AND 2100)
);

-- ---------------------------------------------------------------------
-- AIRPORTS
-- ---------------------------------------------------------------------
CREATE TABLE airports (
  airport_id    NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH 1000)
                CONSTRAINT pk_airports PRIMARY KEY,
  iata_code     VARCHAR2(3)  NOT NULL
                CONSTRAINT uq_airports_code UNIQUE
                CONSTRAINT ck_airports_code CHECK (REGEXP_LIKE(iata_code, '^[A-Z]{3}$')),
  airport_name  VARCHAR2(80) NOT NULL,
  city          VARCHAR2(40) NOT NULL,
  country       VARCHAR2(40) NOT NULL
);

-- ---------------------------------------------------------------------
-- AIRCRAFT
-- ---------------------------------------------------------------------
CREATE TABLE aircraft (
  aircraft_id     NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH 1000)
                  CONSTRAINT pk_aircraft PRIMARY KEY,
  airline_id      NUMBER NOT NULL
                  CONSTRAINT fk_aircraft_airline REFERENCES airlines (airline_id) ON DELETE CASCADE,
  registration_no VARCHAR2(12) NOT NULL
                  CONSTRAINT uq_aircraft_reg UNIQUE,
  aircraft_model  VARCHAR2(40) NOT NULL,
  total_seats     NUMBER(4) NOT NULL
                  CONSTRAINT ck_aircraft_seats CHECK (total_seats BETWEEN 1 AND 900),
  status          VARCHAR2(12) DEFAULT 'ACTIVE' NOT NULL
                  CONSTRAINT ck_aircraft_status CHECK (status IN ('ACTIVE', 'MAINTENANCE', 'RETIRED'))
);

-- ---------------------------------------------------------------------
-- FLIGHTS
-- departure_time < arrival_time is enforced by trigger
-- trg_flights_validate_times (06_triggers.sql).
-- ---------------------------------------------------------------------
CREATE TABLE flights (
  flight_id         NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH 1000)
                    CONSTRAINT pk_flights PRIMARY KEY,
  flight_no         VARCHAR2(8) NOT NULL,
  airline_id        NUMBER NOT NULL
                    CONSTRAINT fk_flights_airline REFERENCES airlines (airline_id) ON DELETE CASCADE,
  aircraft_id       NUMBER
                    CONSTRAINT fk_flights_aircraft REFERENCES aircraft (aircraft_id) ON DELETE SET NULL,
  origin_airport_id NUMBER NOT NULL
                    CONSTRAINT fk_flights_origin REFERENCES airports (airport_id),
  dest_airport_id   NUMBER NOT NULL
                    CONSTRAINT fk_flights_dest REFERENCES airports (airport_id),
  departure_time    DATE NOT NULL,
  arrival_time      DATE NOT NULL,
  base_fare         NUMBER(10,2) NOT NULL
                    CONSTRAINT ck_flights_fare CHECK (base_fare > 0),
  status            VARCHAR2(10) DEFAULT 'SCHEDULED' NOT NULL
                    CONSTRAINT ck_flights_status
                    CHECK (status IN ('SCHEDULED', 'DELAYED', 'CANCELLED', 'DEPARTED', 'ARRIVED')),
  CONSTRAINT uq_flights_no_dep UNIQUE (flight_no, departure_time),
  CONSTRAINT ck_flights_route  CHECK (origin_airport_id <> dest_airport_id)
);

-- ---------------------------------------------------------------------
-- PASSENGERS
-- ---------------------------------------------------------------------
CREATE TABLE passengers (
  passenger_id  NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH 1000)
                CONSTRAINT pk_passengers PRIMARY KEY,
  first_name    VARCHAR2(30) NOT NULL,
  last_name     VARCHAR2(30) NOT NULL,
  email         VARCHAR2(80) NOT NULL
                CONSTRAINT uq_passengers_email UNIQUE
                CONSTRAINT ck_passengers_email CHECK (REGEXP_LIKE(email, '^[^@ ]+@[^@ ]+\.[^@ ]+$')),
  phone         VARCHAR2(15) NOT NULL
                CONSTRAINT ck_passengers_phone CHECK (REGEXP_LIKE(phone, '^[0-9]{10}$')),
  date_of_birth DATE NOT NULL,
  gender        CHAR(1) NOT NULL
                CONSTRAINT ck_passengers_gender CHECK (gender IN ('M', 'F', 'O')),
  passport_no   VARCHAR2(12)
                CONSTRAINT uq_passengers_passport UNIQUE,
  created_at    DATE DEFAULT SYSDATE NOT NULL
);

-- ---------------------------------------------------------------------
-- SEATS  (sellable seat inventory, one row per seat per flight)
-- ---------------------------------------------------------------------
CREATE TABLE seats (
  seat_id     NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH 1000)
              CONSTRAINT pk_seats PRIMARY KEY,
  flight_id   NUMBER NOT NULL
              CONSTRAINT fk_seats_flight REFERENCES flights (flight_id) ON DELETE CASCADE,
  seat_no     VARCHAR2(4) NOT NULL,
  seat_class  VARCHAR2(10) NOT NULL
              CONSTRAINT ck_seats_class CHECK (seat_class IN ('ECONOMY', 'BUSINESS', 'FIRST')),
  status      VARCHAR2(10) DEFAULT 'AVAILABLE' NOT NULL
              CONSTRAINT ck_seats_status CHECK (status IN ('AVAILABLE', 'BOOKED')),
  CONSTRAINT uq_seats_flight_seat UNIQUE (flight_id, seat_no)
);

-- ---------------------------------------------------------------------
-- BOOKINGS
-- Cancelled bookings are kept (status = 'CANCELLED') for history.
-- ---------------------------------------------------------------------
CREATE TABLE bookings (
  booking_id    NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH 1000)
                CONSTRAINT pk_bookings PRIMARY KEY,
  passenger_id  NUMBER NOT NULL
                CONSTRAINT fk_bookings_passenger REFERENCES passengers (passenger_id) ON DELETE CASCADE,
  seat_id       NUMBER NOT NULL
                CONSTRAINT fk_bookings_seat REFERENCES seats (seat_id),
  booking_date  DATE DEFAULT SYSDATE NOT NULL,
  status        VARCHAR2(10) DEFAULT 'CONFIRMED' NOT NULL
                CONSTRAINT ck_bookings_status CHECK (status IN ('CONFIRMED', 'CANCELLED')),
  cancelled_at  DATE,
  CONSTRAINT ck_bookings_cancel CHECK (
        (status = 'CONFIRMED' AND cancelled_at IS NULL)
     OR (status = 'CANCELLED' AND cancelled_at IS NOT NULL))
);

-- At most one CONFIRMED booking per seat. Cancelled rows map to NULL,
-- and NULL keys are not indexed, so any number of them can coexist.
CREATE UNIQUE INDEX uq_bookings_active_seat
  ON bookings (CASE WHEN status = 'CONFIRMED' THEN seat_id END);

-- ---------------------------------------------------------------------
-- PAYMENTS  (exactly one payment per booking)
-- ---------------------------------------------------------------------
CREATE TABLE payments (
  payment_id      NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH 1000)
                  CONSTRAINT pk_payments PRIMARY KEY,
  booking_id      NUMBER NOT NULL
                  CONSTRAINT uq_payments_booking UNIQUE
                  CONSTRAINT fk_payments_booking REFERENCES bookings (booking_id) ON DELETE CASCADE,
  amount          NUMBER(10,2) NOT NULL
                  CONSTRAINT ck_payments_amount CHECK (amount > 0),
  payment_method  VARCHAR2(12) NOT NULL
                  CONSTRAINT ck_payments_method
                  CHECK (payment_method IN ('CARD', 'UPI', 'NETBANKING', 'WALLET', 'CASH')),
  status          VARCHAR2(10) DEFAULT 'SUCCESS' NOT NULL
                  CONSTRAINT ck_payments_status CHECK (status IN ('SUCCESS', 'REFUNDED')),
  transaction_ref VARCHAR2(20) NOT NULL
                  CONSTRAINT uq_payments_txn UNIQUE,
  payment_date    DATE DEFAULT SYSDATE NOT NULL,
  refund_amount   NUMBER(10,2) DEFAULT 0 NOT NULL,
  refund_date     DATE,
  CONSTRAINT ck_payments_refund CHECK (refund_amount >= 0 AND refund_amount <= amount)
);

-- ---------------------------------------------------------------------
-- CREW and the FLIGHT_CREW junction (many-to-many flights <-> crew)
-- ---------------------------------------------------------------------
CREATE TABLE crew (
  crew_id          NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH 1000)
                   CONSTRAINT pk_crew PRIMARY KEY,
  airline_id       NUMBER NOT NULL
                   CONSTRAINT fk_crew_airline REFERENCES airlines (airline_id) ON DELETE CASCADE,
  full_name        VARCHAR2(60) NOT NULL,
  crew_role        VARCHAR2(15) NOT NULL
                   CONSTRAINT ck_crew_role
                   CHECK (crew_role IN ('CAPTAIN', 'FIRST_OFFICER', 'PURSER', 'CABIN_CREW')),
  license_no       VARCHAR2(20) NOT NULL
                   CONSTRAINT uq_crew_license UNIQUE,
  experience_years NUMBER(2) DEFAULT 0 NOT NULL
                   CONSTRAINT ck_crew_experience CHECK (experience_years BETWEEN 0 AND 45),
  phone            VARCHAR2(15)
);

CREATE TABLE flight_crew (
  flight_id    NUMBER NOT NULL
               CONSTRAINT fk_fc_flight REFERENCES flights (flight_id) ON DELETE CASCADE,
  crew_id      NUMBER NOT NULL
               CONSTRAINT fk_fc_crew REFERENCES crew (crew_id) ON DELETE CASCADE,
  assigned_on  DATE DEFAULT SYSDATE NOT NULL,
  CONSTRAINT pk_flight_crew PRIMARY KEY (flight_id, crew_id)
);

-- ---------------------------------------------------------------------
-- BOOKING_AUDIT_LOG
-- Deliberately has NO foreign key to bookings: the log must survive
-- when a booking is deleted (e.g. cascade from a deleted passenger).
-- ---------------------------------------------------------------------
CREATE TABLE booking_audit_log (
  log_id       NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH 1000)
               CONSTRAINT pk_booking_audit PRIMARY KEY,
  booking_id   NUMBER NOT NULL,
  action       VARCHAR2(6) NOT NULL
               CONSTRAINT ck_audit_action CHECK (action IN ('INSERT', 'UPDATE', 'DELETE')),
  old_status   VARCHAR2(10),
  new_status   VARCHAR2(10),
  old_seat_id  NUMBER,
  new_seat_id  NUMBER,
  changed_by   VARCHAR2(30) DEFAULT USER NOT NULL,
  changed_at   DATE DEFAULT SYSDATE NOT NULL
);

-- ---------------------------------------------------------------------
-- Indexes on foreign keys (speeds joins and avoids table-level locks
-- when parent rows are deleted). Unique constraints already index
-- seats.flight_id, payments.booking_id and flight_crew.flight_id.
-- ---------------------------------------------------------------------
CREATE INDEX idx_aircraft_airline    ON aircraft (airline_id);
CREATE INDEX idx_flights_airline     ON flights (airline_id);
CREATE INDEX idx_flights_aircraft    ON flights (aircraft_id);
CREATE INDEX idx_flights_origin      ON flights (origin_airport_id);
CREATE INDEX idx_flights_dest        ON flights (dest_airport_id);
CREATE INDEX idx_bookings_passenger  ON bookings (passenger_id);
CREATE INDEX idx_bookings_seat       ON bookings (seat_id);
CREATE INDEX idx_crew_airline        ON crew (airline_id);
CREATE INDEX idx_fc_crew             ON flight_crew (crew_id);
CREATE INDEX idx_audit_booking       ON booking_audit_log (booking_id);

